\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  - 23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Werner Rolevinck}}\plain \f1\b\lang1033\fs24 :] {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Fasciculus temporum omnes antiquorum cronicas complectens}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5210/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 unvollst\u228 \'e4ndig}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ) [Prolog] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 GEneracio et generacio laudabit opera tua et potenciam tuam}}\plain \f1\i\lang1033\fs24  ...;
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [Text] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >I<N principio creauit deus celum et terram etc. dicit beatus Augustinus super Genesim}}\plain \f1\lang1033\fs24  ... - (zum Jahr 1474) \plain \f1\i\lang1033\fs24 hortabatur quoque ut ad resistendum se disponeret.\plain \f1\lang1033\fs24  Mit der herausgetrennten Lage fehlt der Bereich a.\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Chr. 460 - p. Chr. 353. Abschrift einer Inkunabel, vgl. HAIN, 6914-6946; HC\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 2436-2438. Zur handschriftlichen \u220 \'dcberlieferung vgl. H. WOLFFGRAM, Neue\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Forschungen zu Werner Rolevink's Leben und Werken, Zs. f. vaterl\u228 \'e4nd.\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Gesch. u. Alterthumskunde 48,1 (1890), S. 85 -136, hier S. 117 -119 ; C. F.\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 B\u220 \'dcHLER, \plain \f1\i\lang1033\fs24 The Fasciculus Temporum\plain \f1\lang1033\fs24  and Morgan Manuscript 801, Speculum\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 27 (1952), S.178-183; G. MAYER, Autor - Drucker - Publikum. Werner Rolevincks\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 "Fasciculus temporum" und Anton Sorgs Versuch einer deutschen\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Ausgabe, BFB 4 (1976), S. 225-235, hier S. 230, Anm.9; A. DEROLEZ, The Library\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 of Raphael de Marcatellis, Gent 1979, S. 31-34; G. MELVILLE, Geschichte\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 in graphischer Gestalt, in: Geschichtsschreibung und Geschichtsbewusstsein\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 im sp\u228 \'e4ten Mittelalter, hrsg. v. H. PATZE, Sigmaringen 1987 (Vortr\u228 \'e4ge\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 und Forschungen 31), S. 57 -154, hier S, 79 -82; \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 VL 8, Sp. 156 f.; diese Hs. in\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 der Sekund\u228 \'e4rliteratur nicht genannt. 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Anm.: Die Berliner Hs. lat. fol. 72 wurde von Ludolph Hoddelsen de Lemego in Erfurt aus einem Druck von 1478 abgeschrieben, vgl. ROSE, Berlin II,3, Nr. 915, S. 1111-1113.}

