\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Proemium mit Gru\u223 \'dfformel an die Universit\u228 \'e4t Bologna. (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Dedikationsbild}}\plain \f1\lang1033\fs24 , s. o. (65\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Explicit apparatus dni. Johannis Andree super Clementinis.\plain \f1\lang1033\fs24  Zus\u228 \'e4tzliche {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Glossen}}\plain \f1\lang1033\fs24  \u252 \'fcberwiegend von H\u228 \'e4nden des 14. Jhs, die mit den Siglen zahlreicher Juristen subskribiert sind, vgl.: 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Genz\plain \f1\lang1033\fs24 ., 4\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Genzelinus\plain \f1\lang1033\fs24  et passim ({\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Zenzelinus de Cassanis}}\plain \f1\lang1033\fs24 ); 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Pau\plain \f1\lang1033\fs24 ., 1\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Paulus\plain \f1\lang1033\fs24  et p. ({\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus de Liazariis}}\plain \f1\lang1033\fs24 ); 1\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Guillus\plain \f1\lang1033\fs24 . 4\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Gwil\plain \f1\lang1033\fs24 ., 5\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Guillus de Monte Laud\plain \f1\lang1033\fs24 ., 7\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Will\plain \f1\lang1033\fs24 . et p. ({\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Guilelmus de Monte Lauduno}}\plain \f1\lang1033\fs24 ); 4\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Maynardus\plain \f1\lang1033\fs24 , 36\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 May\plain \f1\lang1033\fs24 ., 54\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Mey\plain \f1\lang1033\fs24 . et p. (Meinhard, vgl. NESKE, N\u252 \'fcrnberg, StB 3, S. 14 zu {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cent. I, 23, 1}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24 ); 5\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Archid\plain \f1\lang1033\fs24 ., 37\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ar\plain \f1\lang1033\fs24 . et p. (Archidiaconus = {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Guido de Baisio}}\plain \f1\lang1033\fs24 ); 5\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 hos\plain \f1\lang1033\fs24 ., 10\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Hosti\plain \f1\lang1033\fs24 . et p. (Hostiensis = {\field{\*\fldinst HYPERLINK "hida://bezper[6].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Henricus de Segusia}}\plain \f1\lang1033\fs24 ); seltener: 5\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ste\plain \f1\lang1033\fs24 ., 18\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Stephanus\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[7].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stephanus Provincialis?}}\plain \f1\lang1033\fs24 , vgl. NESKE, N\u252 \'fcrnberg, StB 3, S. 14 zu {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cent. I, 23, 1}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24  SCHULTE, GQ 2, S. 200f.); 7\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ste. Truce\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[8].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u201 \'c9tienne Troches}}\plain \f1\lang1033\fs24 ); 7\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Jo. Mo.\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[9].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Monachus}}\plain \f1\lang1033\fs24 ); 18\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Jo. An.\plain \f1\lang1033\fs24  ({\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Andreae}}\plain \f1\lang1033\fs24 ) ; 9\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  et p. eigene Glossen von \plain \f1\i\lang1033\fs24 Ry\plain \f1\lang1033\fs24 . ({\field{\*\fldinst HYPERLINK "hida://bezper[10].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Ryman}}\plain \f1\lang1033\fs24 ).
