\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Fol max 30b,10:
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Ein Doppelbl.  \u183 \'b7  Schriftraum 24,5 x 13,5-14, mit Glosse 26,5-29,5 x 24-24,5  \u183 \'b7  2 Spalten mit Klammerglosse  \u183 \'b7  55-59 Zeilen Text; Kommentar 65-90 Zeilen  \u183 \'b7  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Textualis}}\plain \f1\lang1033\fs20  in 2 Schriftgraden  \u183 \'b7  rubriziert  \u183 \'b7  3zeilige Lombarden abwechselnd in Rot und Blau, gelegentlich mit Zierstrich in der Gegenfarbe  \u183 \'b7  zur Aufbewahrung s. o. Fol max 30b.}

