\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (144\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -145\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) [Prolog] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >S<Apiencia patris et ipsa veritas dei scilicet filius}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  [144\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Idcirca ego Johannes de Dobergoz plebanus a simplicibus sacerditibus rogatus ... pro exemplacione ewangeliorum per anni circulum ... hunc laborem aggredior ...\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >C<irca aduentum domini notandum prima quod quadruplex est aduentus domini}}\plain \f1\lang1033\fs24  ..., (145\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) [Text] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >E<runt signa ... (Lc 21,25). In hoc ewangelio agitur de adventu saluatoris ad iudicium}}\plain \f1\lang1033\fs24  ...; (146\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 -147\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >I<Ohannes cum audiebat [!] ... (Mt 11,2). In hoc ewangelio agitur de adventu saluatoris in mentem}}\plain \f1\lang1033\fs24  ...; (147\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -148\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >M<iserunt Judei ... (Io 1,19). Primo in hoc ewangelio agitur de Christo [!] adventu saluatoris quando natus fuit in mundum}}\plain \f1\lang1033\fs24  ... - (292\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -293\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >A<beuntes pharisaei ... (Mt 22,15). In hac dominica de sancta conuersatione et vite puritate admonemur}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ...; (293\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -294\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >L<oquente Jhesu ... (Mt 9,18). Hec dominica vocans [!] in qua agitur de lapide angulari}}\plain \f1\lang1033\fs24  ...; (294\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 -296\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >C<um subleuasset ... (Io 6,5). In hac dominica xxiiij quasi per totum officium diuine miserationis}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  - (295\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ita per\plain \f1\lang1033\fs24  [296\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 prudentiam deciperetur\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Laudemus ergo\plain \f1\lang1033\fs24  ... Vgl. SCHNEYER, Wegweiser, S.455, S. 243; auch vorhanden in Hamburg, SuUB, Cod. Petri 17, vgl. BRANDIS/MAEHLER, Hamburg IV, S. 34 f. Die Predigten auf 293\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  und 294\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24  auch in Hamburg, SuUB, Cod. Petri 35, 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  bzw. 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  enthalten und dort Gilbertus Tornacensis zugeschrieben, vgl. BRANDIS/MAEHLER, Hamburg IV, S. 78; sie fehlen bei SCHNEYER, Repertorium 2, S. 282-318.}

