\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (228\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [Prolog] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >M<Andastis, Reuerendissime pater et domine prestantissime}}\plain \f1\i\lang1033\fs24  domine Juliane\plain \f1\lang1033\fs24  ... , (228\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [Text] {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >Q<Vestio prima est utrum supra episcopos aliquis dandus sit}}\plain \f1\i\lang1033\fs24  superior in ecclesia. Ad hanc questionem respondet sanctus Thomas\plain \f1\lang1033\fs24  ... - (252\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 ut eum emendet uel de medio subtrahat. Hec ille. Expliciunt flores sentenciarum beate Thome de Aquino et de auctoritate summi pontificis collecti per ... Johannem de Turrecremata ... Anno domini 1437 ...; \plain \f1\lang1033\fs24 diese Schlu\u223 \'dfformel auch in N\u252 \'fcrnberg, StB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cent. III, 83}}\plain \f1\lang1033\fs24 , 27\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 , vgl. SCHNEIDER,\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 StB N\u252 \'fcrnberg II,1, S.235. Drucke: HAIN 15732, fo1.263a ff.; Venedig\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 1562. KAEPPELI, Nr.2714, diese Hs. nicht genannt.}

