\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 *1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Notiz}}\plain \f1\lang1033\fs24  \u252 \'fcber die 1605 erfolgte Umgestaltung der Hs. mit Ermahnung zur Sorgfalt im Umgang mit dem Band. Eine \u228 \'e4hnliche Notiz befindet sich in dem Lektionar Berlin, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 theol. lat. fol. 488}}\plain \f1\lang1033\fs24 , vgl. ROSE, Berlin II,2, S. 742.}

