\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Fragm. (vorderer und hinterer Spiegel, jetzt lose) \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  2 aufeinander folgende Doppelbl. aus einer Lage; die Lagenmitte fehlt \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  Schriftraum 19,5x13 \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  2 Spalten \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  32 Zeilen \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Textualis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 13. Jh., Mitte}}\plain \f1\lang1033\fs24  \plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  nicht liturgisches lat. {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Kalendar}}\plain \f1\lang1033\fs24  f\u252 \'fcr M\u228 \'e4rz bis Juni mit goldenen Zahlen f\u252 \'fcr das Mondalter, Sonntagsbuchstaben und Kalenden, am rechten Rand die Lunarbuchstaben f\u252 \'fcr die Ostertage; nachtr\u228 \'e4gliche {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Nekrolog-Eintr\u228 \'e4ge}}\plain \f1\lang1033\fs24  von mehreren H\u228 \'e4nden des 14. Jhs, wahrscheinlich aus dem Augustinerinnenkloster {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6923/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Niederm\u252 \'fcnster}}\plain \f1\lang1033\fs24  in Saint-Nabor, Kr. Molsheim, Bas-Rhin: {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Heinricus Metziger}}\plain \f1\i\lang1033\fs24  schultetus\plain \f1\lang1033\fs24  [nachgewiesen 1310 als Schiedsrichter (Arch. D\u233 \'e9p. Bas-Rhin 39J 20), 1336 und 1346 (Urkundenbuch der Stadt Stra\u223 \'dfburg, Bd. 7, Nr. 153 und 503) und 1348 (Stadtarchiv Oberehnheim FF 1)] \plain \f1\i\lang1033\fs24 in Ehenheim\plain \f1\lang1033\fs24  [Oberehnheim, frz. Obernai, Kr. S\u233 \'e9lestat-Erstein, Bas-Rhin]; \plain \f1\i\lang1033\fs24 ad capallam s. Iacobi \plain \f1\lang1033\fs24 [bei Saint-Nabor]{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Otto Pincerna}}\plain \f1\lang1033\fs24  [Otto Schenk d. A. und Otto Schenk d. J. in einer Urkunde von 1292 nachgewiesen, vgl. J. M. Gyss, Histoire de la ville d\rquote Obernai, Stra\u223 \'dfburg 1866, Bd. I, S. 75] \plain \f1\i\lang1033\fs24 de Ehenheim, Ottenrode\plain \f1\lang1033\fs24  [Ottrott, Kr. S\u233 \'e9lestat-Erstein, Bas-Rhin], \plain \f1\i\lang1033\fs24 Eberhardus clericus de Landesberg, {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Frischo de Ottenrode}}\plain \f1\i\lang1033\fs24  frater noster\plain \f1\lang1033\fs24  [1297 urkundlich belegt als \u8222 \'84Frische de Ottenrode\ldblquote  und \u8222 \'84Fridericus sacrista inferioris monasterii\ldblquote  des Klosters Niederm\u252 \'fcnster im Stra\u223 \'dfburger Bezirksarchiv = Archives d\u233 \'e9partementales du Bas-Rhin, G 2759/6], \plain \f1\i\lang1033\fs24 Rulinus plebanus in Rosheim\plain \f1\lang1033\fs24  [Kr. Molsheim, Bas-Rhin], \plain \f1\i\lang1033\fs24 Gisela div meisterin, Gisela elemosinaria, Sigelinus frater noster, Heinricus laicus, Sifridus pater meus, Hermannus de Dierstein can. arg.\plain \f1\lang1033\fs24  [zwei Kanoniker im Stra\u223 \'dfburger Domstift trugen diesen Namen und sind zwischen 1260 und 1325 belegt, vgl. R. P. LEVRESSE, Prosopographie du chapitre cath\u233 \'e9dral de Strasbourg 1092-1593, Archives de l\rquote Eglise d\rquote Alsace 34 (NS 18) (1970), S. 1-39], \plain \f1\i\lang1033\fs24 Hedewig, Anno domini M\u176 \'b0\plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\i\lang1033\fs24 CCC\u176 \'b0\plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\i\lang1033\fs24 XXI\u176 \'b0 .... Adelheidis mater mea, Gertrudis celleraria mea, Cvonradus presbiter hospitalis, Johannes presbiter hospitalis, Isenhardus ca\plain \f1\lang1033\fs24 [...], \plain \f1\i\lang1033\fs24 Kleinhannes de Ehenheim, Johannes de Ehenheim can. sancti Leonardi\plain \f1\lang1033\fs24  [Stift St. Leonhard bei B\u246 \'f6rsch, Kr. Molsheim) \plain \f1\i\lang1033\fs24 ... anno domini M\u176 \'b0\plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\i\lang1033\fs24 CCC\u176 \'b0\plain \f1\lang1033\fs20  \u183 \'b7 \plain \f1\i\lang1033\fs24 lx\u176 \'b0, {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ditherus Faber de Ehenheim}}\plain \f1\lang1033\fs24  [ein Theodericus Faber de Ehenhein nachgewiesen 1382 im Urkundenbuch der Stadt Stra\u223 \'dfburg, Bd. 6, Nr. 106], {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Wilhellmus burcgrauius}}\plain \f1\lang1033\fs24  [von Osthofen? belegt 1308-25, Stra\u223 \'dfburger UB IV/1, 184, Nr. 298 und 185, Anm. 1; Inventar des Bezirksarchivs Stra\u223 \'dfburg, G 119/1 und G 1352/2], \plain \f1\i\lang1033\fs24 Hedewig can. de Ehenheim.\plain \f1\lang1033\fs24  3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Breviarium}}\plain \f1\lang1033\fs24 ; nachweisbar: Corpus Christi mit {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 50 Nr. 386 und 387}}\plain \f1\lang1033\fs24 .}

