\par \pard\fi0\li0\qc\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20 Bl. 1-28, Bl. 32a-32c und Bl. 33  \u183 \'b7  Wz.: Bl. 24 und 25 Dreiberg mit Kreuz, Typ PICCARD VII, Nr. 2353 (1483), nicht identisch mit dem Wz. auf Bl. 48 und 49  \u183 \'b7  V\plain \f1\super\lang1033\fs20 10\plain \f1\lang1033\fs20  + (VI+1)\plain \f1\super\lang1033\fs20 23\plain \f1\lang1033\fs20  + (V-1)\plain \f1\super\lang1033\fs20 33\plain \f1\lang1033\fs20 ; nach Bl. 32a ein Falz von einem herausgeschnittenen, beschriebenen Blatt; zwischen Bl. 28 und 32a zwei Doppelbll. (Faszikel II) eingef\u252 \'fcgt  \u183 \'b7  Schriftraum 12-13,5x7-8  \u183 \'b7  21-26 Zeilen  \u183 \'b7  1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -28\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Bastarda}}\plain \f1\lang1033\fs20  von einer Hand; 33\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Nachtrag, Bastarda  \u183 \'b7  rubriziert  \u183 \'b7  2zeilige rote Lombarden und Anfangsbuchstaben, z. T. mit ornamentalen Aussparungen  \u183 \'b7  1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  zwei 2zeilige Blattwerk-Initialen, \u8222 \'84\plain \f1\i\lang1033\fs20 A\plain \f1\lang1033\fs20 \ldblquote  in Blau mit wei\u223 \'dfer H\u246 \'f6hung, ein olivfarbener Akanthusblatt-Abl\u228 \'e4ufer, im Binnenraum Blattmotive in Violett und Ros\u233 \'e9; \u8222 \'84\plain \f1\i\lang1033\fs20 D\plain \f1\lang1033\fs20 \ldblquote  in Oliv und Schwarz mit blauen Blattmotiven im Binnenraum  \u183 \'b7  18teiliger Bilderzyklus zur Passion Christi; 8x8 bis 13x7,5 jeweils mit einem ein Zentimeter breiten Rahmen; schlichte Federzeichnungen; 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -11\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  koloriert (gr\u252 \'fcn, blau, rostrot, violettrot, goldfarben, gelb, schwarz); 12\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 -27\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  z. T. mit Rot und Schwarz koloriert: 2\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gefangennahme Christi}}\plain \f1\lang1033\fs20 ; 2\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kaiphas zerrei\u223 \'dft sein Gewand}}\plain \f1\lang1033\fs20 ; 3\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Christus vor Hannas}}\plain \f1\lang1033\fs20 ; 4\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Jacobus und 2 weitere Apostel benachrichtigen Maria; 6\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Adoratio crucis, vor dem Kreuz betet ein M\u246 \'f6nch im schwarzen Gewand; 7\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  Maria mit 2 Frauen; 8\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Christus vor Pilatus}}\plain \f1\lang1033\fs20 ; 11\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Schaustellung Christi}}\plain \f1\lang1033\fs20 ; 12\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Gei\u223 \'dfelung Christi}}\plain \f1\lang1033\fs20 ; 12\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Dornenkr\u246 \'f6nung}}\plain \f1\lang1033\fs20 ; 13\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kreuztragung}}\plain \f1\lang1033\fs20 ; 13\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Christus zusammengebrochen unter der Kreuzeslast}}\plain \f1\lang1033\fs20 ; 17\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Entkleidung Christi und Kreuzannagelung}}\plain \f1\lang1033\fs20 ; 17\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Christus am T-Kreuz mit den Sch\u228 \'e4chern, Maria und Johannes und anderen Zuschauern}}\plain \f1\lang1033\fs20 ; 21\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[11]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Lanzenstich}}\plain \f1\lang1033\fs20 ; 24\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[12]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Kreuzabnahme}}\plain \f1\lang1033\fs20 ; 24\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[13]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Piet\u224 \'e0}}\plain \f1\lang1033\fs20 ; 27\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5500[14]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Grablegung}}\plain \f1\lang1033\fs20 .}

