\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Auch vorhanden in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 GB 8\u186 \'ba 116}}\plain \f1\lang1033\fs24 , 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , vgl. VENNEBUSCH, K\u246 \'f6ln III, S.111 und Trier, StB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 572/804 8\u186 \'ba}}\plain \f1\lang1033\fs24 , 106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , vgl. Trier, Bd. V, S. 31 f. Die Weimarer \u220 \'dcberlieferung weicht stark von der Trierer ab. Weimar 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zeitweise mit Trier 106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -119\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \u252 \'fcbereinstimmend, danach v\u246 \'f6llig unterschiedlich. Zum Verfasser und zum Werk vgl. U. BERLI\u200 \'c8RE, Thierry de Homborch O. S. B., abb\u233 \'e9 de Bursfeld \u8224 \'86 1485, Revue liturgique et monastique 14 (1928), S. 78-86; P. ENGELBERT, in: Die Benediktinerkl\u246 \'f6ster in Niedersachsen, Schleswig-Holstein und Bremen, bearb. v. U. FAUST, St. Ottilien 1979, S. 508.}

