\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Ob reuerenciam omnium wlnerum Ihesu Christi dic xv pater noster et cottidem Aue Maria eum orationibus sequentibus\plain \f1\lang1033\fs24 <. (24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >A<ue manus dextra Cristi / wlnerata plaga tristi}}\plain \f1\lang1033\fs24 ..., auch vorhanden in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Oct 64}}\plain \f1\lang1033\fs24 , 108\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  CHEVALIER, 1869; HAIMERL, S.80, Anm. 459, 92, Anm. 541, 124, Anm. 732, 177; PAULUS III, S.295; (247\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >D<omine Ihesu Christe qui pro salute generis humani crucifigi, wlnerari et lanceari}}\plain \f1\lang1033\fs24 ... , auch vorhanden in {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Oct 64}}\plain \f1\lang1033\fs24 , 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; vgl. DANIEL, M\u252 \'fcnchen UB 4, S.247 zu {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 8\u176 \'b0 Cod. ms. 211}}\plain \f1\lang1033\fs24 , 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; HAIMERL, S.127; (248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) [{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Jacobus Mediolanensis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Stimulus amoris}}\plain \f1\b\lang1033\fs24  minor\plain \f1\lang1033\fs24 ], Auszug. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >D<omine Ihesu Christe cor meum tuis wlneribus saucia}}\plain \f1\i\lang1033\fs24 ...,\plain \f1\lang1033\fs24  auch vorhanden in {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Oct 64}}\plain \f1\lang1033\fs24 , 110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; (248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >P<Er tuum transuerberatum cor transfige amantissime domine Ihesu Christe vnigenite summi patris cor meum}}\plain \f1\i\lang1033\fs24 ...;\plain \f1\lang1033\fs24  (248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 >J<hesu benignissime qui crucem sanctam ascendisti et Mariam}}\plain \f1\i\lang1033\fs24  matrem tuam sub te stantem..., \plain \f1\lang1033\fs24 auch vorhanden in {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Oct 62}}\plain \f1\lang1033\fs24 , 93\plain \f1\super\lang1033\fs32 v\plain \f1\lang1033\fs24 ; vgl. BUSHEY, Trier I, S. 43 zu Hs. {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 494/1596 8\u176 \'b0}}\plain \f1\lang1033\fs24 , 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 .}

