tum hoc inspirante}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ...; (206\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item legitur quod abbas Agathon lapidem per triennium}}\plain \f1\i\lang1033\fs24  ..., \plain \f1\lang1033\fs24 vgl. ANDERSSON-SCHMIDT/HEDLUND, Uppsala UB, Bd. 4, S. 106 zu {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 C 313}}\plain \f1\lang1033\fs24 , 45\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  und Bd. 8, S. 430; (206\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 -207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\b\lang1033\fs24 [{\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Gerardus de Fracheto}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Vitae Fratrum Ordinis Praedicatorum}}\plain \f1\b\lang1033\fs24 ]\plain \f1\lang1033\fs24 , Auszug. \plain \f1\i\lang1033\fs24 Ex legenda sancti Dominici. {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Monachus quidam ante ordinis predicatorum institutionem}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ..., Edition: B. REICHERT, L\u246 \'f6wen 1896 (Monumenta Ordinis Fratrum Praedicatorum historica 1), hier S. 6-9, Text stark abweichend; vgl. KAEPPELI, Nr. 1282; (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quidam frater minor qui multo tempore socius sancti Francisci extiterat}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \plain \f1\i\lang1033\fs24 narravit quod cum beatus Dominicus Rome ..\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 apud papam instaret \plain \f1\lang1033\fs24 ...; (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 [B]Eatus Dominicus cum mansisset in partibus Tholosanis}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ...; (208\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -209\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Miraculum de institutione festi corporis Christi. {\field{\*\fldinst HYPERLINK "hida://5650[10].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tempore quo Vrbanus papa ... cum suis fratribus cardinalibus}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ...\plain \f1\i\lang1033\fs24  fuit quidam sacerdos teuthonicus \plain \f1\lang1033\fs24 ... - \plain \f1\i\lang1033\fs24 alius prelatus se haberi possunt missam celebret, \plain \f1\lang1033\fs24 vgl. KERN, UB Graz II, S. 161 zu {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hs. 967}}\plain \f1\lang1033\fs24 , 302\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; (209\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) 7 kurze Exempel;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (210\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Nicolaus de Dinkelspuhel}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 De Nativitate Domini sermo}}\plain \f1\b\lang1033\fs24  IIIa\plain \f1\lang1033\fs24 ,\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Auszug. \plain \f1\i\lang1033\fs24 Ex quodam sermone Nycoli Dinkelspol de nativitate Christi. {\field{\*\fldinst HYPERLINK "hida://5650[11].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Notandum quod bonum est sui diffusivum}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ..., vgl. MADRE, S. 208; (210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[12].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Petite et accipietis ... (Io 16,24). Vbi notatur quod triplex est gaudium}}\plain \f1\i\lang1033\fs24  ...; \plain \f1\lang1033\fs24 (211\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) leer;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (212\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Jacobus de Voragine}}\plain \f1\b\lang1033\fs24  (?): {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo \u8222 \'84Aeterne nequam\ldblquote }}\plain \f1\b\lang1033\fs24 ,\plain \f1\lang1033\fs24  Auszug. \plain \f1\i\lang1033\fs24 Ex quodam sermone {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iacobi de Voragine}}\plain \f1\i\lang1033\fs24  ... {\field{\*\fldinst HYPERLINK "hida://5650[13].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ingratitudo est grave vicium et quinque mala facit}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 Ex sermone ... qui incipit Eterne nequam; \plain \f1\lang1033\fs24 (212\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Notate. \plain \f1\i\lang1033\fs24 De fructu passionis Christi; \plain \f1\lang1033\fs24 (213\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Jacobus de Voragine}}\plain \f1\b\lang1033\fs24  (?): {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermo de sancta trinitate}}\plain \f1\lang1033\fs24 , Auszug. {\field{\*\fldinst HYPERLINK "hida://5650[14].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Quod scimus loquimur et quod vidimus testamur}}\plain \f1\lang1033\fs24  ... - \plain \f1\i\lang1033\fs24 Hec {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Jacobus de Voragine}}\plain \f1\i\lang1033\fs24  in quodam sermone de sancta trinitate;\plain \f1\lang1033\fs24  (214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[18].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Qualiter memoria passionis Christi agatur in missa.}}\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[15].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nota quod sacerdos prima amictum capitus [capitis!] superponit hoc significat}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 - \plain \f1\i\lang1033\fs24 In domo patris\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 mei mansiones multe sunt, \plain \f1\lang1033\fs24 am Rand die Zahlen \plain \f1\i\lang1033\fs24 1-28\plain \f1\lang1033\fs24 ; dieser Text auch oben 115\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 -117\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ;\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 (215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  und 216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  mittlerer Abschnitt) {\field{\*\fldinst HYPERLINK "hida://5650[16].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item quando homo veraciter resurgit a peccatis et conuertitur}}\plain \f1\i\lang1033\fs24  ...; \plain \f1\lang1033\fs24 (215\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[17].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nemo sumat sibi honorem nisi qui vocatur a deo}}\plain \f1\i\lang103